61	/**
62	 * Manages all the nodes for Jenkins.
63	 *
64	 * @since 1.607
65	 */
66	@Restricted(NoExternalUse.class) // for now, we may make it public later
67	public class Nodes implements PersistenceRoot {
68	
69	    private static final Logger LOGGER = Logger.getLogger(Nodes.class.getName());
70	
71	    /**
72	     * Determine if we need to enforce the name restrictions during node creation or replacement.
73	     * Should be enabled (default) to prevent SECURITY-2021.
74	     */
75	    @Restricted(NoExternalUse.class)
76	    private static final boolean ENFORCE_NAME_RESTRICTIONS = SystemProperties.getBoolean(Nodes.class.getName() + ".enforceNameRestrictions", true);
77	
78	    /**
79	     * The {@link Jenkins} instance that we are tracking nodes for.
80	     */
81	    @NonNull
82	    private final Jenkins jenkins;
83	
84	    /**
85	     * The map of nodes.
86	     */
87	    private final ConcurrentMap<String, Node> nodes = new ConcurrentSkipListMap<>();
88	
89	    /**
90	     * Constructor, intended to be called only from {@link Jenkins}.
91	     *
92	     * @param jenkins A reference to the {@link Jenkins} that this instance is tracking nodes for, beware not to
93	     *                let this reference escape from a partially constructed {@link Nodes} as when we are passed the
94	     *                reference the {@link Jenkins} instance has not completed instantiation.
95	     */
96	    /*package*/ Nodes(@NonNull Jenkins jenkins) {
97	        this.jenkins = jenkins;
98	    }
99	
100	    /**
101	     * Returns the list of nodes.
102	     *
103	     * @return the list of nodes.
104	     */
105	    @NonNull
106	    public List<Node> getNodes() {
107	        return new ArrayList<>(nodes.values());
108	    }
109	
110	    /**
111	     * Sets the list of nodes.
112	     *
113	     * @param nodes the new list of nodes.
114	     * @throws IOException if the new list of nodes could not be persisted.
115	     */
116	    public void setNodes(final @NonNull Collection<? extends Node> nodes) throws IOException {
117	        Set<String> toRemove = new HashSet<>();
118	        Queue.withLock(new Runnable() {
119	            @Override
120	            public void run() {
121	                toRemove.addAll(Nodes.this.nodes.keySet());
122	                for (Node n : nodes) {
123	                    final String name = n.getNodeName();
124	                    toRemove.remove(name);
125	                    Nodes.this.nodes.put(name, n);
126	                    n.onLoad(Nodes.this, name);
127	                }
128	                Nodes.this.nodes.keySet().removeAll(toRemove);
129	                jenkins.updateComputerList();
130	                jenkins.trimLabels();
131	            }
132	        });
133	        save();
134	        for (String name : toRemove) {
135	            LOGGER.fine(() -> "deleting " + new File(getRootDir(), name));
136	            Util.deleteRecursive(new File(getRootDir(), name));
137	        }
138	    }
139	
140	    /**
141	     * Adds a node. If a node of the same name already exists then that node will be replaced.
142	     *
143	     * @param node the new node.
144	     * @throws IOException if the list of nodes could not be persisted.
145	     */
146	    public void addNode(final @NonNull Node node) throws IOException {
147	        if (ENFORCE_NAME_RESTRICTIONS) {
148	            Jenkins.checkGoodName(node.getNodeName());
149	        }
150	
151	        Node old = nodes.put(node.getNodeName(), node);
152	        if (node != old) {
153	            node.onLoad(this, node.getNodeName());
154	            jenkins.updateNewComputer(node);
155	            jenkins.trimLabels(node, old);
156	            // TODO there is a theoretical race whereby the node instance is updated/removed after lock release
157	            try {
158	                node.save();
159	            } catch (IOException | RuntimeException e) {
160	                // JENKINS-50599: If persisting the node throws an exception, we need to remove the node from
161	                // memory before propagating the exception.
162	                Queue.withLock(new Runnable() {
163	                    @Override
164	                    public void run() {
165	                        nodes.compute(node.getNodeName(), (ignoredNodeName, ignoredNode) -> old);
166	                        jenkins.updateComputerList();
167	                        jenkins.trimLabels(node, old);
168	                    }
169	                });
170	                throw e;
171	            }
172	            if (old != null) {
173	                NodeListener.fireOnUpdated(old, node);
174	            } else {
175	                NodeListener.fireOnCreated(node);
176	            }
177	        }
178	    }
