192	    /**
193	     * Updates an existing node on disk. If the node instance is not in the list of nodes, then this
194	     * will be a no-op, even if there is another instance with the same {@link Node#getNodeName()}.
195	     *
196	     * @param node the node to be updated.
197	     * @return {@code true}, if the node was updated. {@code false}, if the node was not in the list of nodes.
198	     * @throws IOException if the node could not be persisted.
199	     * @since 1.634
200	     */
201	    public boolean updateNode(final @NonNull Node node) throws IOException {
202	        boolean exists;
203	        try {
204	            exists = Queue.withLock(new Callable<>() {
205	                @Override
206	                public Boolean call() throws Exception {
207	                    if (node == nodes.get(node.getNodeName())) {
208	                        jenkins.trimLabels(node);
209	                        return true;
210	                    }
211	                    return false;
212	                }
213	            });
214	        } catch (RuntimeException e) {
215	            // should never happen, but if it does let's do the right thing
216	            throw e;
217	        } catch (Exception e) {
218	            // can never happen
219	            exists = false;
220	        }
221	        if (exists) {
222	            // TODO there is a theoretical race whereby the node instance is updated/removed after lock release
223	            node.save();
224	            // TODO should this fireOnUpdated?
225	            return true;
226	        }
227	        return false;
228	    }
