230	    /**
231	     * Replace node of given name.
232	     *
233	     * @return {@code true} if node was replaced.
234	     * @since 2.8
235	     */
236	    public boolean replaceNode(final Node oldOne, final @NonNull Node newOne) throws IOException {
237	        if (ENFORCE_NAME_RESTRICTIONS) {
238	            Jenkins.checkGoodName(newOne.getNodeName());
239	        }
240	
241	        if (oldOne == nodes.get(oldOne.getNodeName())) {
242	            // use the queue lock until Nodes has a way of directly modifying a single node.
243	            Queue.withLock(new Runnable() {
244	                @Override
245	                public void run() {
246	                    Nodes.this.nodes.remove(oldOne.getNodeName());
247	                    Nodes.this.nodes.put(newOne.getNodeName(), newOne);
248	                    newOne.onLoad(Nodes.this, newOne.getNodeName());
249	                }
250	            });
251	            updateNode(newOne);
252	            if (!newOne.getNodeName().equals(oldOne.getNodeName())) {
253	                LOGGER.fine(() -> "deleting " + new File(getRootDir(), oldOne.getNodeName()));
254	                Util.deleteRecursive(new File(getRootDir(), oldOne.getNodeName()));
255	            }
256	            Queue.withLock(() -> {
257	                jenkins.updateComputerList();
258	                jenkins.trimLabels(oldOne, newOne);
259	            });
260	            NodeListener.fireOnUpdated(oldOne, newOne);
261	
262	            return true;
263	        } else {
264	            return false;
265	        }
266	    }
