268	    /**
269	     * Removes a node. If the node instance is not in the list of nodes, then this will be a no-op, even if
270	     * there is another instance with the same {@link Node#getNodeName()}.
271	     *
272	     * @param node the node instance to remove.
273	     * @throws IOException if the list of nodes could not be persisted.
274	     */
275	    public void removeNode(final @NonNull Node node) throws IOException {
276	        if (node == nodes.get(node.getNodeName())) {
277	            AtomicBoolean match = new AtomicBoolean();
278	            Queue.withLock(new Runnable() {
279	                @Override
280	                public void run() {
281	                    Computer c = node.toComputer();
282	                    if (c != null) {
283	                        c.recordTermination();
284	                        c.disconnect(OfflineCause.create(hudson.model.Messages._Hudson_NodeBeingRemoved()));
285	                    }
286	                    match.set(node == nodes.remove(node.getNodeName()));
287	                }
288	            });
289	            // no need for a full save() so we just do the minimum
290	            LOGGER.fine(() -> "deleting " + new File(getRootDir(), node.getNodeName()));
291	            Util.deleteRecursive(new File(getRootDir(), node.getNodeName()));
292	
293	            if (match.get()) {
294	                jenkins.updateComputerList();
295	                jenkins.trimLabels(node);
296	            }
297	            NodeListener.fireOnDeleted(node);
298	        }
299	    }
