301	    @Override
302	    public void save() throws IOException {
303	        if (BulkChange.contains(this)) {
304	            return;
305	        }
306	        for (Node n : nodes.values()) {
307	            if (n instanceof EphemeralNode) {
308	                continue;
309	            }
310	            XmlFile xmlFile = getConfigFile(n);
311	            LOGGER.fine(() -> "saving " + xmlFile);
312	            xmlFile.write(n);
313	            SaveableListener.fireOnChange(this, xmlFile);
314	        }
315	    }
