317	    /**
318	     * Returns the named node.
319	     *
320	     * @param name the {@link Node#getNodeName()} of the node to retrieve.
321	     * @return the {@link Node} or {@code null} if the node could not be found.
322	     */
323	    @CheckForNull
324	    public Node getNode(String name) {
325	        return name == null ? null : nodes.get(name);
326	    }
