328	    /**
329	     * Loads the nodes from disk.
330	     *
331	     * @throws IOException if the nodes could not be deserialized.
332	     */
333	    public void load() throws IOException {
334	        final File nodesDir = getRootDir();
335	        final File[] subdirs = nodesDir.listFiles(File::isDirectory);
336	        final Map<String, Node> newNodes = new TreeMap<>();
337	        if (subdirs != null) {
338	            for (File subdir : subdirs) {
339	                try {
340	                    load(subdir, newNodes);
341	                } catch (IOException e) {
342	                    LOGGER.log(Level.WARNING, "could not load " + subdir, e);
343	                }
344	            }
345	        }
346	        Queue.withLock(new Runnable() {
347	            @Override
348	            public void run() {
349	                newNodes.entrySet().removeIf(stringNodeEntry -> ExtensionList.lookup(NodeListener.class).stream().anyMatch(nodeListener -> {
350	                    if (!nodeListener.allowLoad(stringNodeEntry.getValue())) {
351	                        LOGGER.log(Level.FINE, () -> "Loading of node " + stringNodeEntry.getKey() + " vetoed by " + nodeListener);
352	                        return true;
353	                    }
354	                    return false;
355	                }));
356	                nodes.entrySet().removeIf(stringNodeEntry -> !(stringNodeEntry.getValue() instanceof EphemeralNode));
357	                nodes.putAll(newNodes);
358	                jenkins.updateComputerList();
359	                jenkins.trimLabels();
360	            }
361	        });
362	    }
363	
364	    @CheckForNull
365	    public Node getOrLoad(String name) {
366	        Node node = getNode(name);
367	        LOGGER.fine(() -> "already loaded? " + node);
368	        return node == null ? load(name) : node;
369	    }
370	
371	    @CheckForNull
372	    public Node load(String name) {
373	        try {
374	            XmlFile xmlFile = getConfigFile(name);
375	            if (xmlFile.exists()) {
376	                Node n = (Node) xmlFile.read();
377	                nodes.put(n.getNodeName(), n);
378	                n.onLoad(this, n.getNodeName());
379	                jenkins.updateNewComputer(n);
380	                jenkins.trimLabels(n);
381	                LOGGER.finer(() -> "loading " + xmlFile);
382	                return n;
383	            } else {
384	                LOGGER.fine(() -> "no such file " + xmlFile);
385	            }
386	        } catch (IOException e) {
387	            LOGGER.log(Level.WARNING, "could not load " + name, e);
388	        }
389	        return null;
390	    }
391	
392	    private Node load(File dir, Map<String, Node> nodesCollector) throws IOException {
393	        Node n = (Node) getConfigFile(dir).read();
394	        if (n != null) {
395	            nodesCollector.put(n.getNodeName(), n);
396	            n.onLoad(this, n.getNodeName());
397	        }
398	        return n;
399	    }
400	
401	    public void load(File dir) throws IOException {
402	        Node n = load(dir, nodes);
403	        jenkins.updateComputerList();
404	        jenkins.trimLabels(n);
405	    }
