407	    public void unload(Node node) {
408	        if (node == nodes.get(node.getNodeName())) {
409	            AtomicBoolean match = new AtomicBoolean();
410	            Queue.withLock(() -> match.set(node == nodes.remove(node.getNodeName())));
411	            if (match.get()) {
412	                jenkins.updateComputerList();
413	                jenkins.trimLabels(node);
414	            }
415	        }
416	    }
